import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int padding,
    int H_out, int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int oc = tmp % C_out;
    int n = tmp / C_out;

    float sum = bias[oc];

    int h_in_start = oh * stride - padding;
    int w_in_start = ow * stride - padding;

    for (int ic = 0; ic < C_in; ++ic) {
        const float* input_ptr = input + ((n * C_in + ic) * H_in) * W_in;
        const float* weight_ptr = weight + ((oc * C_in + ic) * K) * K;

        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_in_start + kh;
            if (h_in < 0 || h_in >= H_in) continue;
            const float* input_row = input_ptr + h_in * W_in;
            const float* weight_row = weight_ptr + kh * K;

            for (int kw = 0; kw < K; ++kw) {
                int w_in = w_in_start + kw;
                if (w_in < 0 || w_in >= W_in) continue;
                sum += input_row[w_in] * weight_row[kw];
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);

    const int C_out = weight.size(0);
    const int K = weight.size(2);

    const int H_out = (H_in + 2 * padding - K) / stride + 1;
    const int W_out = (W_in + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    int total = N * C_out * H_out * W_out;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    conv2d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, padding,
        H_out, W_out
    );

    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = 3 * 11 * 11
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias = self.bias.contiguous().cuda()
        return conv2d_module.conv2d_forward_cuda(x, weight, bias, self.stride, self.padding)

